// Shared plumbing for this pack's checks.
//
// Deliberately dependency-free: a local pack's check modules must load even when
// the gitignored canon mount is absent (the project's own vitest run is exactly
// that situation), so nothing here imports `engine/checks/helpers/*`. The two
// things every rule needs are a finding constructor and a comment stripper.

/** The plain finding object the checks runner consumes (engine/checks/README.md). */
export function finding(rule, { file, line = null, what, fix, why = null, severity = null }) {
  return {
    rule: rule.id,
    severity: severity || rule.severity,
    file,
    line,
    what,
    why: why || rule.why,
    fix,
    doc: rule.doc,
  };
}

// String-aware comment stripper. Every rule below matches against source *code*:
// a comment that merely names `chrome.tts.speak` or `getUserMedia` describes the
// trap, it doesn't spring it — and this pack's own prose would otherwise fire its
// own checks. Same technique the repo's arch test already uses
// (extension-test/unit/arch.test.js), kept here so the pack stands alone.
// Newlines are preserved so line numbers survive the strip.
export function stripComments(source) {
  let out = '';
  let state = 'code'; // code | line | block | sq | dq | tpl
  for (let i = 0; i < source.length; i++) {
    const c = source[i];
    const c2 = source[i + 1];
    if (state === 'code') {
      if (c === '/' && c2 === '/') { state = 'line'; i++; continue; }
      if (c === '/' && c2 === '*') { state = 'block'; i++; continue; }
      if (c === "'") state = 'sq';
      else if (c === '"') state = 'dq';
      else if (c === '`') state = 'tpl';
      out += c;
    } else if (state === 'line') {
      if (c === '\n') { state = 'code'; out += c; }
    } else if (state === 'block') {
      if (c === '*' && c2 === '/') { state = 'code'; i++; }
      else if (c === '\n') out += c;
    } else {
      out += c;
      if (c === '\\') { out += c2 ?? ''; i++; }
      else if ((state === 'sq' && c === "'") || (state === 'dq' && c === '"') || (state === 'tpl' && c === '`')) {
        state = 'code';
      }
    }
  }
  return out;
}

// What counts as shipped browser source. Deliberately NOT a hard-coded project
// root: every rule in this pack is gated on the speech API it judges actually
// appearing in the file, so the trigger is the API usage itself and the scan can
// safely be repo-shaped. A path scope hard-wired to one project's layout would
// make all three rules match zero files — and pass VACUOUSLY GREEN — in any repo
// laid out differently, which is the worst failure mode a check has.
//
// The one thing the scan must still exclude is test scaffolding: hand-rolled
// speech fakes implement only the halves of a contract a given case exercises,
// and holding purpose-built scaffolding to the production contract is a false
// alarm. That exclusion is expressed directly — by test/vendor path and test
// filename — instead of being a side effect of the source root.
const SOURCE_EXT = /\.(?:m|c)?[jt]sx?$/;
const NOT_SOURCE = [
  /(?:^|\/)(?:node_modules|dist|build|out|coverage|vendor|third_party)\//,
  /(?:^|\/)(?:tests?|__tests__|__mocks__|spec|fixtures?|mocks?|e2e)\//,
  /(?:^|[./-])(?:test|spec|fixture|mock|stub|fake)s?\.[^/]+$/,
];
export const isSource = (file) => SOURCE_EXT.test(file) && !NOT_SOURCE.some((re) => re.test(file));

/** 1-based line number of `index` in `text`. */
export const lineOf = (text, index) => text.slice(0, index).split('\n').length;

/**
 * Both legal ways to wire a speech event, as one matcher: the `onfoo =` property
 * assignment and `addEventListener('foo', …)`. The DOM offers both for every one
 * of these targets and neither is more correct, so a rule that knows only the
 * property form silently passes half the world's code — and false-alarms on a
 * file that mixes the two (`rec.onresult = …` beside
 * `rec.addEventListener('error', …)` reads as "no error handler" to a matcher
 * that only understands `.onerror =`).
 */
export const wires = (src, event) =>
  new RegExp(
    `\\.\\s*on${event}\\s*=|addEventListener\\s*\\(\\s*['"\`]${event}['"\`]`,
  ).test(src);

/** Does `text` contain `name` as a string literal? */
export const quoted = (text, name) => new RegExp(`['"\`]${name}['"\`]`).test(text);

/**
 * The balanced bracketed run beginning at the opener at `open` (inclusive of both
 * brackets), or null when the source is unbalanced — a half-written file should
 * make a check say nothing, never guess. String and template literals are skipped
 * so a bracket inside "a(b)" can't be read as syntax.
 */
export function balanced(src, open) {
  let depth = 0;
  for (let i = open; i < src.length; i++) {
    const c = src[i];
    if (c === '"' || c === "'" || c === '`') {
      const quote = c;
      for (i += 1; i < src.length; i++) {
        if (src[i] === '\\') { i += 1; continue; }
        if (src[i] === quote) break;
      }
      continue;
    }
    if (c === '{' || c === '[' || c === '(') depth += 1;
    else if (c === '}' || c === ']' || c === ')') {
      depth -= 1;
      if (depth === 0) return src.slice(open, i + 1);
    }
  }
  return null;
}

=== .claudinite/local/packs/browser-speech/mic-capture-released.mjs ===
import { finding, stripComments, isSource, lineOf } from './lib.mjs';

// A getUserMedia stream is only released when its TRACKS are stopped. Dropping
// the reference, closing an AudioContext, unsetting a srcObject, or letting the
// function return does not free the device: the browser's recording indicator
// and the OS microphone indicator both stay lit, and on some platforms the
// device stays claimed until the tab closes. On anything voice-driven that is
// the most alarming possible bug — the app looks like it is listening to the
// user when it isn't.
//
// The release belongs in a `finally`, so that no early return, rejection, or
// throw between opening the capture and finishing with it can leave the device
// held — a permission preflight that opens a stream just to learn whether it is
// allowed is the classic instance, since everything it does in between can throw.
//
// Deliberately file-scoped rather than flow-scoped: proving a particular stream
// is stopped needs real data-flow analysis, and a check that guesses is worse
// than one that asks a simple, honest question — "this file opens a capture;
// does it anywhere stop the tracks?". A property reference
// (`if (!media?.getUserMedia)`) is not a call and does not trigger it; comments
// are stripped first.

const CALL = /\bgetUserMedia\s*\(/g;
const RELEASE = /\bgetTracks\b|\bgetAudioTracks\b/;
const STOP = /\.\s*stop\s*\(/;

const rule = {
  id: 'mic-capture-released',
  severity: 'blocking',
  description: 'A file that opens a getUserMedia capture also stops its tracks',
  doc: '.claudinite/local/packs/browser-speech/RULES.md',
  why: 'a media stream is freed only by stopping its tracks — dropping the reference leaves the browser and OS microphone indicators lit and the device claimed, which on anything voice-driven reads to the user as "it is still listening to me"',

  run(ctx) {
    const out = [];
    for (const file of ctx.files) {
      if (!isSource(file)) continue;
      const raw = ctx.read(file);
      if (raw === null || !raw.includes('getUserMedia')) continue;
      const src = stripComments(raw);
      CALL.lastIndex = 0;
      const first = CALL.exec(src);
      if (!first) continue;
      if (RELEASE.test(src) && STOP.test(src)) continue;
      out.push(finding(rule, {
        file,
        line: lineOf(src, first.index),
        what: 'opens a microphone capture but never stops its tracks',
        fix: 'release the capture with stream.getTracks().forEach((t) => t.stop()), and put that call in a `finally` so no early return, rejection, or throw from the code in between can leave the device held',
      }));
    }
    return out;
  },
};

export default rule;

=== .claudinite/local/packs/browser-speech/mic-constraints-not-screen-capture.mjs ===
import { finding, stripComments, isSource, lineOf, balanced } from './lib.mjs';

// `suppressLocalAudioPlayback` and `restrictOwnAudio` are `getDisplayMedia`
// SCREEN-CAPTURE constraints. They filter the playout of a captured tab out of
// that tab's audio track; they say nothing about a microphone, and getUserMedia
// ignores them entirely — no throw, no warning, no `OverconstrainedError`.
//
// They are reached for by name: someone hunting the app's own TTS leaking back
// through the mic reads "suppress local audio playback" / "restrict own audio"
// as exactly the fix, sets it on the mic capture, and ships believing self-echo
// is handled at the capture layer. It isn't, and the code that would have
// handled it (an application-level echo guard) never gets written. That is the
// silent-failure shape this whole pack is about: nothing throws, nothing logs,
// the feature simply doesn't exist.
//
// PARSED, NOT GREPPED. The names are only wrong where they reach a microphone
// capture, so the scan is the balanced argument list of a `getUserMedia(` call —
// plus, one hop, the initializer of any same-file constant that argument list
// references, since hoisting the constraints into a frozen constant is the
// ordinary way to write this:
//
//     const AUDIO = Object.freeze({ echoCancellation: true });
//     await media.getUserMedia({ audio: AUDIO });
//
// Everything outside that reach stays quiet on purpose — a file's real
// getDisplayMedia call, a `getSupportedConstraints()` probe, a screen-capture
// module's own constants table are all legitimate uses of these names, and a
// rule that grepped the file would false-alarm on every one of them. Comments
// are stripped first, so the paragraphs above cannot fire the rule.

const CALL = /\bgetUserMedia\s*\(/g;
const DECL = /\b(?:const|let|var)\s+([A-Za-z_$][\w$]*)\s*=/g;
const OPENER = /^\s*(?:[A-Za-z_$][\w$.]*\s*)?([[{(])/;
const DISPLAY_ONLY = ['suppressLocalAudioPlayback', 'restrictOwnAudio'];

/**
 * The index ranges of `src` that a getUserMedia call's constraints actually
 * reach: the argument list itself, plus the initializer of every same-file
 * `const`/`let`/`var` the argument list names. One hop only — resolving further
 * needs real data-flow analysis, and a check that guesses is worse than one that
 * asks a simple, honest question.
 */
function reach(src, argsStart, args) {
  const regions = [{ start: argsStart, end: argsStart + args.length }];
  DECL.lastIndex = 0;
  for (let d = DECL.exec(src); d; d = DECL.exec(src)) {
    if (!new RegExp(`\\b${d[1]}\\b`).test(args)) continue;
    const eq = d.index + d[0].length;
    const head = OPENER.exec(src.slice(eq));
    if (!head) continue;
    const open = eq + head[0].length - 1;
    const init = balanced(src, open);
    if (init === null) continue;
    regions.push({ start: open, end: open + init.length });
  }
  return regions;
}

const rule = {
  id: 'mic-constraints-not-screen-capture',
  severity: 'blocking',
  description: 'A microphone capture never asks for getDisplayMedia-only constraints',
  doc: '.claudinite/local/packs/browser-speech/RULES.md',
  why: 'suppressLocalAudioPlayback and restrictOwnAudio are getDisplayMedia screen-capture constraints — they filter a captured tab\'s own playout, not a microphone — so getUserMedia silently ignores them while the author believes self-echo is now handled at the capture layer and never writes the guard that would have handled it',

  run(ctx) {
    const out = [];
    for (const file of ctx.files) {
      if (!isSource(file)) continue;
      const raw = ctx.read(file);
      if (raw === null || !DISPLAY_ONLY.some((name) => raw.includes(name))) continue;
      const src = stripComments(raw);
      const seen = new Set();
      CALL.lastIndex = 0;
      for (let m = CALL.exec(src); m; m = CALL.exec(src)) {
        const argsStart = m.index + m[0].length - 1;
        const args = balanced(src, argsStart);
        if (args === null) continue;
        for (const { start, end } of reach(src, argsStart, args)) {
          const region = src.slice(start, end);
          for (const name of DISPLAY_ONLY) {
            const at = region.search(new RegExp(`\\b${name}\\b`));
            if (at === -1) continue;
            const line = lineOf(src, start + at);
            if (seen.has(`${name}:${line}`)) continue;
            seen.add(`${name}:${line}`);
            out.push(finding(rule, {
              file,
              line,
              what: `a getUserMedia microphone capture asks for ${name}, which is a getDisplayMedia screen-capture constraint`,
              fix: `drop ${name} from the microphone constraints — it filters a captured tab's own playout out of a screen-capture track and getUserMedia ignores it outright, so it suppresses nothing here; residual self-echo has to be handled above the capture (an application-level echo guard), because the recognizer's capture takes no constraints at all`,
            }));
          }
        }
      }
    }
    return out;
  },
};

export default rule;

