1	// Grid writing via simulated user input (REQ-PAGE-006/007/008).
2	// Strategy: per-cell click (position-addressed — immune to NYT cursor-skip settings),
3	// then a keydown per letter, then verify by re-reading (never trust, always check).
4	//
5	// Live-page hardening (MT-02 findings):
6	//   - Synthetic key events carry the legacy keyCode/which/charCode fields — the live
7	//     app's handlers read those, and a bare {key} event constructs them as 0.
8	//   - The live page renders asynchronously (React), so verification POLLS the DOM
9	//     instead of reading it synchronously right after the last dispatch.
10	// Further fallbacks if the live page ignores untrusted events: dev/docs/FEASIBILITY.md §3.
11	//
12	// Pencil mode (REQ-PAGE-012): cells may carry a `pencil` flag; letters are typed with
13	// the page's pencil toggle driven to match, and the toggle is restored afterwards so
14	// the user's own typing mode is never stolen. Success stays judged on letters — a page
15	// whose pencil markup drifted degrades the softening (REQ-ANS-019), not answering.
16	
17	import { snapshot, cellElements } from './reader.js';
18	import { SEL, CLS, findPencilToggle } from './selectors.js';
19	
20	const settle = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
21	
22	function fire(el, type, init) {
23	  const view = el.ownerDocument?.defaultView ?? globalThis;
24	  const Ctor = type.startsWith('key') ? view.KeyboardEvent : view.MouseEvent;
25	  el.dispatchEvent(new Ctor(type, { bubbles: true, cancelable: true, composed: true, ...init }));
26	}
27	
28	export function clickCell(cellEl) {
29	  fire(cellEl, 'mousedown', {});
30	  fire(cellEl, 'mouseup', {});
31	  fire(cellEl, 'click', {});
32	}
33	
34	const LEGACY_KEYCODE = { Backspace: 8 };
35	
36	function keyEventInit(key) {
37	  const letter = /^[A-Z]$/.test(key);
38	  const keyCode = letter ? key.charCodeAt(0) : (LEGACY_KEYCODE[key] ?? 0);
39	  return { key, code: letter ? `Key${key}` : key, keyCode, which: keyCode };
40	}
41	
42	// Key events must bubble THROUGH the app's root container: the live page delegates key
43	// handling near its own root (React-style), and that root is a DESCENDANT of <body> — an
44	// event dispatched on body bubbles up past document without ever passing through it.
45	// Prefer the element the app focused (the selected cell's rect carries tabindex=0);
46	// otherwise aim at a board cell so the event still traverses the app root.
47	function keyTarget(document, cellEl) {
48	  const active = document.activeElement;
49	  if (active && active !== document.body && active !== document.documentElement) return active;
50	  return cellEl ?? document.querySelector(SEL.cell) ?? document.body;
51	}
52	
53	function typeKey(document, key, cellEl) {
54	  const target = keyTarget(document, cellEl);
55	  const init = keyEventInit(key);
56	  fire(target, 'keydown', init);
57	  if (/^[A-Z]$/.test(key)) fire(target, 'keypress', { ...init, charCode: init.keyCode });
58	  fire(target, 'keyup', init);
59	}
60	
61	/**
62	 * Tell NYT a user is present WITHOUT touching the puzzle (REQ-LIFE-017). A bare Shift
63	 * types no letter and moves no cursor, but it is a real keydown/keyup — and NYT's
64	 * ~30 s inactivity timer resets on keydown (verified live), so this keeps a quiet puzzle
65	 * from auto-pausing. Driven by the conversation: sent on every heard user command, since
66	 * a voice solver isn't touching the keyboard between them. When the user goes quiet
67	 * instead, no nudge is sent, NYT pauses, and the session ends (REQ-LIFE-011).
68	 */
69	export function keepAlive(document) {
70	  const target = keyTarget(document);
71	  const init = { key: 'Shift', code: 'ShiftLeft', keyCode: 16, which: 16 };
72	  fire(target, 'keydown', init);
73	  fire(target, 'keyup', init);
74	}
75	
76	function pencilToggle(document) {
77	  return findPencilToggle(document);
78	}
79	
80	// Class markers that would say "this toggle is ON" (none observed live yet — the
81	// probe's pencil forensics exist to capture one when the user finds it).
82	const ACTIVE_CLASS = /(^|[-_])(active|selected|pressed|on)([-_]|$)/i;
83	
84	/**
85	 * Pencil-mode signal from the page: true/false when readable, or NULL when the markup
86	 * carries no state at all — the live button is `<button><i class="xwd__toolbar_icon--
87	 * pencil"></i></button>` with no aria-pressed and no class change (verified live,
88	 * 2026-07), so blindness is the NORMAL case and the writer falls back to click parity.
89	 */
90	function pencilModeOn(document) {
91	  const el = pencilToggle(document);
92	  if (!el) return null;
93	  const pressed = el.getAttribute('aria-pressed');
94	  if (pressed != null) return pressed === 'true';
95	  const carriers = [el, ...el.querySelectorAll('[class]'), el.closest('li')].filter(Boolean);
96	  for (const c of carriers) {
97	    const cls = c.getAttribute('class') ?? '';
98	    if (cls.split(/\s+/).includes(CLS.pencilActive)) return true;
99	    if (ACTIVE_CLASS.test(cls)) return true;
100	  }
101	  return null; // no readable state — derive from our own click parity
102	}
103	
104	/**
105	 * Poll the grid until `want(cellsByIndex)` passes or the deadline expires; at the
106	 * deadline `judge(cellsByIndex)` decides `ok`. The final snapshot is returned either
107	 * way, so failures stay honest (REQ-ANS-013).
108	 */
109	async function verify(document, want, judge, { verifyTimeoutMs, pollMs }) {
110	  const deadline = Date.now() + verifyTimeoutMs;
111	  for (;;) {
112	    const snap = snapshot(document);
113	    const byIndex = new Map(snap.cells.map((c) => [c.index, c]));
114	    if (want(byIndex)) return { ok: true, snapshot: snap };
115	    if (Date.now() >= deadline) return { ok: judge(byIndex), snapshot: snap };
116	    await settle(pollMs);
117	  }
118	}
119	
120	/**
121	 * @param {Document} document
122	 * @param {Array<{index: number, letter: string, pencil?: boolean}>} cells
123	 * @param {{verifyTimeoutMs?: number, pollMs?: number, keySettleMs?: number}} [opts]
124	 * @returns {Promise<{ok: boolean, snapshot: object}>} ok = every targeted cell now shows its letter
125	 */
126	export async function enterAnswer(document, cells, opts = {}) {
127	  const { verifyTimeoutMs = 1500, pollMs = 50, keySettleMs = 15 } = opts;
128	  const els = cellElements(document);
129	  const detected = pencilModeOn(document); // true | false | null (live page: null)
130	  const wasPencilOn = detected ?? false; // blind ⇒ assume the common case: pen
131	  let toggleClicks = 0;
132	
133	  // Drive the toggle to `target`. When the page exposes no state (the live button —
134	  // see pencilModeOn), the current mode is derived from the assumed start + our own
135	  // click count, which guarantees a net-zero number of clicks over the whole write:
136	  // even blind, the user's toggle is never stolen (REQ-PAGE-012).
137	  const setPencilMode = async (target) => {
138	    const el = pencilToggle(document);
139	    if (!el) return;
140	    const current = pencilModeOn(document)
141	      ?? ((wasPencilOn ? 1 : 0) + toggleClicks) % 2 === 1;
142	    if (current === Boolean(target)) return;
